-- Intermediate model for user-level ecommerce analytics.
--
-- This model builds on the staging layer and prepares
-- reusable user-level metrics for downstream marts.
--
-- Business grain:
-- one row per user and one time window.
--
-- Grain:
-- (window_start, window_end, user_id)

SELECT
    window_start,
    window_end,
    user_id,

    -- Event activity
    total_events,
    views,
    add_to_carts,
    purchases,

    -- Revenue generated by the user
    revenue,

    -- Product engagement
    unique_products,

    -- Existing purchase rate
    purchase_rate,

    -- Average revenue generated per purchase.
    --
    -- We protect the division by zero because a user
    -- can have activity without making a purchase.
    CASE
        WHEN purchases > 0
        THEN revenue / purchases
        ELSE 0
    END AS revenue_per_purchase,

    -- Average number of events generated per distinct product.
    --
    -- We protect the division by zero because a user
    -- may theoretically have no product associated with events.
    CASE
        WHEN unique_products > 0
        THEN total_events::NUMERIC / unique_products
        ELSE 0
    END AS events_per_product

FROM {{ ref('stg_user_metrics') }}